CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,domain text NOT NULL CHECK(domain='platinumbleutls.com'));
CREATE TABLE members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL UNIQUE CHECK(email=lower(email) AND email ~ '^[^@]+@platinumbleutls[.]com$'),name text NOT NULL,subject text UNIQUE,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended')),roles text[] NOT NULL DEFAULT '{}',permission_version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE TABLE login_transactions(id text PRIMARY KEY,state_hash text NOT NULL,nonce text NOT NULL,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY,member_id uuid NOT NULL REFERENCES members(id),csrf text NOT NULL,permission_version int NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE INDEX session_member_idx ON sessions(member_id);
CREATE TABLE customers(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,email text,phone text,address text,external_id text,source text NOT NULL DEFAULT 'app',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source,external_id));
CREATE INDEX customer_email_idx ON customers(tenant_id,email);
CREATE INDEX customer_phone_idx ON customers(tenant_id,phone);
CREATE TABLE jobs(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),customer_id uuid NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','ready','scheduled','in_progress','complete','canceled')),approved_at timestamptz,agreement_at timestamptz,deposit_required_minor bigint CHECK(deposit_required_minor>=0),deposit_paid_minor bigint NOT NULL DEFAULT 0 CHECK(deposit_paid_minor>=0),starts_at timestamptz,ends_at timestamptz,source text NOT NULL DEFAULT 'app',external_id text,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),UNIQUE(tenant_id,source,external_id),CHECK(ends_at IS NULL OR ends_at>starts_at));
CREATE TABLE assignments(tenant_id uuid NOT NULL,job_id uuid NOT NULL,member_id uuid NOT NULL,PRIMARY KEY(tenant_id,job_id,member_id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id),FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id));
CREATE TABLE resources(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid DEFAULT gen_random_uuid(),name text NOT NULL,kind text NOT NULL CHECK(kind IN('person','equipment')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id));
CREATE TABLE reservations(tenant_id uuid NOT NULL,id uuid DEFAULT gen_random_uuid(),job_id uuid NOT NULL,resource_id uuid NOT NULL,during tstzrange NOT NULL,status text NOT NULL DEFAULT 'confirmed' CHECK(status IN('confirmed','released')),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id),CHECK(NOT isempty(during) AND NOT lower_inf(during) AND NOT upper_inf(during) AND lower_inc(during) AND NOT upper_inc(during)),EXCLUDE USING gist(tenant_id WITH =,resource_id WITH =,during WITH &&) WHERE(status='confirmed'));
CREATE TABLE leads(tenant_id uuid NOT NULL,id uuid DEFAULT gen_random_uuid(),customer_id uuid NOT NULL,stage text NOT NULL DEFAULT 'new' CHECK(stage IN('new','qualified','estimate','follow_up','won','lost')),source text,next_action text,next_action_at timestamptz,owner_id uuid,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),FOREIGN KEY(tenant_id,owner_id) REFERENCES members(tenant_id,id));
CREATE TABLE invoices(tenant_id uuid NOT NULL,id uuid DEFAULT gen_random_uuid(),job_id uuid NOT NULL,number text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','issued','part_paid','paid','void')),currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'),lines jsonb NOT NULL,total_minor bigint NOT NULL CHECK(total_minor>=0),due_date date,approved_by uuid,approved_at timestamptz,source text NOT NULL DEFAULT 'app',external_id text,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,number),UNIQUE(tenant_id,source,external_id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id),FOREIGN KEY(tenant_id,approved_by) REFERENCES members(tenant_id,id));
CREATE FUNCTION protect_issued_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN('issued','part_paid','paid','void') AND (NEW.lines IS DISTINCT FROM OLD.lines OR NEW.total_minor IS DISTINCT FROM OLD.total_minor OR NEW.job_id IS DISTINCT FROM OLD.job_id OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.number IS DISTINCT FROM OLD.number) THEN RAISE EXCEPTION 'Issued invoice revision is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_immutable BEFORE UPDATE ON invoices FOR EACH ROW EXECUTE FUNCTION protect_issued_invoice();
CREATE TABLE documents(tenant_id uuid NOT NULL,id uuid DEFAULT gen_random_uuid(),job_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0 AND size_bytes<=20971520),classification text NOT NULL CHECK(classification IN('job','financial')),object_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'quarantine' CHECK(status IN('quarantine','ready','rejected')),sha256 text,uploader_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id),FOREIGN KEY(tenant_id,uploader_id) REFERENCES members(tenant_id,id));
CREATE TABLE import_batches(tenant_id uuid NOT NULL,id uuid DEFAULT gen_random_uuid(),rows jsonb NOT NULL,status text NOT NULL DEFAULT 'review' CHECK(status IN('review','committed')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES members(tenant_id,id));
CREATE TABLE audit_events(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,entity_id uuid,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE connections(tenant_id uuid NOT NULL REFERENCES tenants(id),provider text NOT NULL CHECK(provider IN('housecall','quickbooks','gmail','calendar','drive','notion')),account_id text,status text NOT NULL DEFAULT 'not_connected',last_success_at timestamptz,cursor jsonb NOT NULL DEFAULT '{}',detail text,PRIMARY KEY(tenant_id,provider));
CREATE TABLE commands(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid DEFAULT gen_random_uuid(),provider text NOT NULL,kind text NOT NULL,entity_id uuid,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','applied','rejected','uncertain')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE webhook_inbox(tenant_id uuid NOT NULL REFERENCES tenants(id),provider text NOT NULL,event_key text NOT NULL,body jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,provider,event_key));
CREATE TABLE idempotency(tenant_id uuid NOT NULL REFERENCES tenants(id),member_id uuid NOT NULL,key text NOT NULL,hash text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,member_id,key));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customers','jobs','assignments','resources','reservations','leads','invoices','documents','import_batches','audit_events','connections','commands','webhook_inbox','idempotency'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
